def rrf(lists, k=60):
    score = defaultdict(float)
    for lst in lists:                     # each sorted best-first
        for rank, pid in enumerate(lst, start=1):
            score[pid] += 1.0 / (k + rank)
    return sorted(score, key=score.get, reverse=True)

def rank(q, cands, deadline):
    l1 = sorted(cands, key=lambda c: w1*c.bm25 + w2*c.pop + w3*c.rating, reverse=True)[:500]
    try:
        F = feature_store.batch_get(q, l1, timeout=min(15, deadline.left()))
        s = model.predict(F, timeout=min(30, deadline.left()))
        l2 = [c for _, c in sorted(zip(s, l1), reverse=True)]
    except Timeout:
        metrics.inc('ranker_fallback'); l2 = l1
    return policy.apply(l2)

for each boosting round:
    for each query group g:
        for pairs (i, j) with label_i > label_j:
            rho = 1 / (1 + exp(s_i - s_j))
            delta = |NDCG(swap i,j) - NDCG|
            lambda_i += rho * delta * ipw(pos_i); lambda_j -= rho * delta * ipw(pos_j)
    fit regression tree to lambdas; s += lr * tree(x)
